<script setup>
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { online, percent, bytes } from '../utils/metrics.js'
import { osIcon, traffic, billing, daysLeft, uptimeText, loadValues, nodeNotes } from '../utils/display.js'
import { now, region, text } from '../composables/useView.js'
import { themeOptions, language } from '../composables/useTheme.js'
import MetricRing from './MetricRing.vue'
import CarrierWindows from './CarrierWindows.vue'
const props = defineProps({ server: Object, site: Object, siteIndex: Number, view: String })
const router = useRouter(), live = computed(() => online(props.server, now.value)), quota = computed(() => traffic(props.server))
const price = computed(() => props.site.sysConfig.show_price === true && themeOptions.value.show_price !== false ? billing(props.server, language.value) : '')
const days = computed(() => props.site.sysConfig.show_expire === true ? daysLeft(props.server.expire_date, now.value) : null)
const metric = (used, total) => live.value && Number(total) > 0 ? percent(used, total) : null
const meters = computed(() => [ { label: 'CPU', value: live.value ? Number(props.server.cpu) : null, detail: `${props.server.cpu_cores || '—'} vCPU` }, { label: 'RAM', value: metric(props.server.ram_used, props.server.ram_total), detail: `${bytes(Number(props.server.ram_used) * 1048576)} / ${bytes(Number(props.server.ram_total) * 1048576)}` }, { label: 'DISK', value: metric(props.server.disk_used, props.server.disk_total), detail: `${bytes(Number(props.server.disk_used) * 1048576)} / ${bytes(Number(props.server.disk_total) * 1048576)}` }, ...(props.site.sysConfig.show_tf !== false ? [{ label: 'USE', value: quota.value.limit ? quota.value.percentage : null, detail: quota.value.detail }] : []) ])
const open = () => router.push({ path: `/server/${props.server.id}`, query: { site: props.siteIndex } })
</script>
<template><article class="cf-card terminal-panel" :class="{ offline: !live }" role="link" tabindex="0" @click="open" @keydown.enter.self="open"><div class="card-heading"><strong><img v-if="region(server.region)" class="country-flag" :src="`${site.base}/flags/${region(server.region).toLowerCase()}.svg`" :alt="region(server.region)"><img v-if="osIcon(server.os)" class="os-icon" :src="`${site.base}/os-icons/${osIcon(server.os)}`" :alt="server.os">{{ server.name || server.id }}</strong><span class="status" :class="live ? 'green' : 'red'">{{ text(live ? '在线' : '离线', live ? 'Online' : 'Offline') }}</span></div><div class="card-meta"><span v-if="price">💰 {{ price }}</span><span v-if="days !== null">📅 {{ days }} {{ text('天', 'days') }}</span><span class="tags"><b v-if="region(server.region)" class="tag-country">{{ region(server.region) }}</b><b v-if="server.arch" class="tag-arch">{{ server.arch }}</b></span></div><div v-if="view === 'ring'" class="rings"><div v-for="meter in meters.slice(0, 3)" :key="meter.label"><MetricRing :value="meter.value" :swap="meter.label === 'RAM' && Number(server.swap_total) > 0 && live ? percent(server.swap_used, server.swap_total) : undefined"/><strong>{{ meter.label }}</strong><small>{{ meter.detail }}</small></div></div><div v-else class="meters"><div v-for="meter in meters" :key="meter.label" class="meter-line" :title="meter.detail"><label>{{ meter.label }}</label><div class="meter-track"><i :style="{ width: `${Math.max(0, Math.min(100, meter.value || 0))}%`, background: meter.value >= 80 ? 'var(--orange)' : meter.label === 'CPU' ? 'var(--blue)' : 'var(--green)' }"/></div><span>{{ meter.value === null || !Number.isFinite(meter.value) ? '—' : `${meter.value.toFixed(2)}%` }}</span></div></div><div class="stat-line"><label>{{ text('负载', 'LOAD') }}</label><span>{{ live ? loadValues(server.load_avg).map(value => value.toFixed(2)).join(' ') || '—' : '—' }}</span></div><div class="stat-line"><label>{{ text('网速', 'NET') }}</label><span class="green">▼ {{ live ? bytes(server.net_in_speed) + '/s' : '—' }} <span class="blue">▲ {{ live ? bytes(server.net_out_speed) + '/s' : '—' }}</span></span></div><div class="stat-line"><label>{{ text('流量', 'TRF') }}</label><span class="green">▼ {{ bytes(server.net_rx) }} <span class="blue">▲ {{ bytes(server.net_tx) }}</span></span></div><div class="card-bottom"><span>{{ text('运行 ', 'Up ') }}{{ uptimeText(server.boot_time, now, language) }}</span><span>TCP {{ live ? server.tcp_conn ?? '—' : '—' }} / UDP {{ live ? server.udp_conn ?? '—' : '—' }}</span></div><div v-if="nodeNotes(server).length" class="public-remark">{{ nodeNotes(server).join(' · ') }}</div><CarrierWindows v-if="themeOptions.show_latency !== false" :server="server" :site="site"/></article></template>
